using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Recovers the 2-step verification password using a recovery code sent to an email address that was previously set up
    /// </summary>
    public Task<TdLib.TdApi.Objects.PasswordState> RecoverPasswordAsync(string recoveryCode = default, string newPassword = default, string newHint = default)
    {

           using var activity =  StartCallActivity("RecoverPasswordAsync", typeof(RecoverPassword).FullName ?? "RecoverPasswordAsync");

           try
           {
             return client.RecoverPasswordAsync(recoveryCode, newPassword, newHint);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
